_MISSING_PATH_METHOD = object()
_PATH_TYPE = type(Path("."))
_PATH_TYPE_METHODS = ("exists", "is_symlink", "lstat", "mkdir", "rglob", "stat")
_ORIGINAL_PATH_TYPE_METHODS = {
    name: _PATH_TYPE.__dict__.get(name, _MISSING_PATH_METHOD)
    for name in _PATH_TYPE_METHODS
}


def restore_path_type_method_shadows() -> None:
    for name, original in _ORIGINAL_PATH_TYPE_METHODS.items():
        if original is _MISSING_PATH_METHOD:
            if name in _PATH_TYPE.__dict__:
                delattr(_PATH_TYPE, name)
        else:
            setattr(_PATH_TYPE, name, original)


REPO_ROOT = Path(__file__).resolve().parents[2]


def create_complete_matrix(root: Path, signer: dict[str, Path | str]) -> None:
    for index, family in enumerate(slot_helpers.device_lab.KAGEMUSHA_STANDARD_DEVICE_FAMILIES):
        slot_helpers.create_slot(root, f"slot-{index}", family, signer)


def direct_android_signed_evidence_report(
    *,
    slot: str = "slot-0",
    family: str | None = None,
    **kagemusha_overrides: object,
) -> dict[str, object]:
    if family is None:
        family = slot_helpers.device_lab.KAGEMUSHA_STANDARD_DEVICE_FAMILIES[0]
    kagemusha: dict[str, object] = {
        "device_family": family,
        "device_fingerprint_sha256": "1" * 64,
        "attestation_challenge_sha256": "2" * 64,
        "signed_at_utc": readiness.DEFAULT_MIN_SIGNED_AT_UTC,
        "signed_evidence_artifact_sha256": "3" * 64,
        "signed_evidence_signer_public_key_sha256": "4" * 64,
        "offline_wallet_apk_path": "evidence/offline-wallet-release.apk",
        "offline_wallet_apk_sha256": "5" * 64,
        "d2d_payment_transcript_path": "handoff/d2d-payment.json",
        "d2d_payment_transcript_sha256": "6" * 64,
        "wallet_integrity_transcript_path": "wallet/integrity.json",
        "wallet_integrity_transcript_sha256": "7" * 64,
        "attestation_certificate_chain_path": "attestation/keymint-certificate-chain.pem",
        "attestation_certificate_chain_sha256": "8" * 64,
    }
    kagemusha.update(kagemusha_overrides)
    return {"status": "ok", "slot": slot, "kagemusha": kagemusha}


def write_json(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def create_lineage_proof_evidence(root: Path) -> Path:
    create_lineage_artifact_files(root)
    create_compact_key_evidence(root)
    proof_log = root / readiness.LINEAGE_PROOF_REQUIRED_TEST_LOGS["record_archive_proof"]
    write_passing_lineage_proof_log(proof_log)
    evidence_path = root / "lineage-proof-evidence.json"
    write_json(
        evidence_path,
        {
            "schema": readiness.LINEAGE_PROOF_EVIDENCE_SCHEMA,
            "generated_at_utc": readiness.DEFAULT_MIN_SIGNED_AT_UTC,
            "opening_len": readiness.EXPECTED_LINEAGE_PROOF_OPENING_LEN,
            "ipa_k": readiness.EXPECTED_LINEAGE_PROOF_IPA_K,
            "verifier_backend": readiness.EXPECTED_LINEAGE_PROOF_BACKEND,
            "verifier_witness_profile": readiness.EXPECTED_LINEAGE_VERIFIER_WITNESS_PROFILE,
            "record_archive_proof_runtime_keygen_env": "unset",
            "circuit_ids": dict(readiness.EXPECTED_LINEAGE_CIRCUIT_IDS),
            "artifacts": {
                artifact: hashlib.sha256((root / artifact).read_bytes()).hexdigest()
                for artifact in readiness.LINEAGE_PROOF_REQUIRED_ARTIFACTS
            },
            "artifact_size_bytes": {
                artifact: (root / artifact).stat().st_size
                for artifact in readiness.LINEAGE_PROOF_REQUIRED_ARTIFACTS
            },
            "tests": {
                "record_archive_proof": {
                    "name": readiness.LINEAGE_PROOF_REQUIRED_TESTS["record_archive_proof"],
                    "status": "passed",
                    "ignored": True,
                    "command": readiness.expected_lineage_proof_command(
                        readiness.LINEAGE_PROOF_REQUIRED_TESTS["record_archive_proof"]
                    ),
                    "elapsed_seconds": 14400.0,
                    "log_path": readiness.LINEAGE_PROOF_REQUIRED_TEST_LOGS[
                        "record_archive_proof"
                    ],
                    "log_sha256": hashlib.sha256(proof_log.read_bytes()).hexdigest(),
                }
            },
        },
    )
    return evidence_path


def create_lineage_artifact_files(root: Path) -> None:
    for artifact in readiness.LINEAGE_PROOF_REQUIRED_ARTIFACTS:
        path = root / artifact
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(f"lineage artifact {artifact}\n".encode("utf-8"))


def create_lineage_artifact_files_for_profile(root: Path, profile: str) -> None:
    if profile == "init":
        artifacts = readiness.LINEAGE_PROOF_REQUIRED_ARTIFACTS[:4]
    elif profile == "append":
        artifacts = readiness.LINEAGE_PROOF_REQUIRED_ARTIFACTS[4:]
    else:
        raise AssertionError(f"unexpected lineage profile {profile}")
    for artifact in artifacts:
        path = root / artifact
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(f"generated {profile} lineage artifact {artifact}\n".encode("utf-8"))


def write_lineage_staged_run_report(
    root: Path,
    *,
    exit_code: int = 0,
    command: str | None = None,
    elapsed_seconds: float = 14400.0,
    key_log_size_overrides: dict[str, int] | None = None,
    proof_log_size_bytes: int | None = None,
) -> Path:
    proof_log = root / readiness.LINEAGE_PROOF_REQUIRED_TEST_LOGS["record_archive_proof"]
    if proof_log_size_bytes is None:
        proof_log_size_bytes = proof_log.stat().st_size
    key_logs: dict[str, dict[str, object]] = {}
    for profile, log_name in {
        "init": "lineage-init-key-artifacts.log",
        "append": "lineage-append-key-artifacts.log",
    }.items():
        log_path = root / log_name
        if not log_path.exists():
            log_path.write_text(
                f"{profile} lineage key artifacts generated\n",
                encoding="utf-8",
            )
        key_logs[profile] = {
            "path": log_name,
            "size_bytes": (
                key_log_size_overrides[profile]
                if key_log_size_overrides and profile in key_log_size_overrides
                else log_path.stat().st_size
            ),
        }
    report = {
        "schema": lineage_finalizer.STAGED_RUN_REPORT_SCHEMA,
        "command": command or evidence_helper.DEFAULT_RECORD_ARCHIVE_PROOF_COMMAND,
        "exit_code": exit_code,
        "elapsed_seconds": elapsed_seconds,
        "lineage_key_artifact_logs": key_logs,
        "proof_log_path": readiness.LINEAGE_PROOF_REQUIRED_TEST_LOGS[
            "record_archive_proof"
        ],
        "proof_log_size_bytes": proof_log_size_bytes,
    }
    path = root / lineage_finalizer.RUN_REPORT_FILENAME
    path.write_text(
        json.dumps(report, allow_nan=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    return path


def write_lineage_execution_report(
    root: Path,
    profile: str,
    *,
    exit_code: int = 0,
    command: str | None = None,
    log_name: str | None = None,
    log_sha256: str | None = None,
) -> Path:
    if profile == "proof":
        phase = "lineage proof command"
        command = command or lineage_staged_runner.DEFAULT_RECORD_ARCHIVE_PROOF_COMMAND
        log_name = log_name or readiness.LINEAGE_PROOF_REQUIRED_TEST_LOGS[
            "record_archive_proof"
        ]
    else:
        phase = f"{profile} lineage key artifact command"
        command = command or lineage_staged_runner.LINEAGE_KEY_ARTIFACT_COMMANDS[profile]
        log_name = log_name or lineage_staged_runner.LINEAGE_KEY_ARTIFACT_LOG_FILENAMES[
            profile
        ]
    log_path = root / log_name
    if not log_path.exists():
        log_path.write_text(f"{profile} staged log\n", encoding="utf-8")
    if log_sha256 is None:
        log_sha256 = hashlib.sha256(log_path.read_bytes()).hexdigest()
    report = {
        "schema": lineage_staged_runner.EXECUTION_REPORT_SCHEMA,
        "phase": phase,
        "command": command,
        "exit_code": exit_code,
        "elapsed_seconds": 1.0,
        "log_path": log_name,
        "log_sha256": log_sha256,
        "log_size_bytes": log_path.stat().st_size,
    }
    path = root / lineage_staged_runner.LINEAGE_EXECUTION_REPORT_FILENAMES[profile]
    path.write_text(
        json.dumps(report, allow_nan=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    return path


def create_compact_key_artifact_files_without_log(root: Path) -> None:
    for artifact in readiness.COMPACT_KEY_REQUIRED_ARTIFACTS:
        path = root / artifact
        path.parent.mkdir(parents=True, exist_ok=True)
        digest = hashlib.sha256(f"fixture compact artifact {artifact}".encode("utf-8")).digest()
        path.write_bytes(b"KCGK\x00\x01" + digest + digest[::-1])


def create_compact_key_artifact_files(root: Path) -> None:
    create_compact_key_artifact_files_without_log(root)
    write_compact_key_generator_log(root)


