    def test_kagemusha_release_bundle_evidence_entries_reject_outside_root_before_hash(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as temp:
            root = Path(temp)
            bundle_root = root / "bundle"
            bundle_root.mkdir()
            outside = root / "outside-artifact.bin"
            outside.write_bytes(b"outside bytes must not be hashed")

            cases = (
                ("digest", release_bundle._evidence_entry, "_sha256_file"),
                (
                    "digest-with-size",
                    release_bundle._evidence_entry_with_size,
                    "_sha256_file_with_size",
                ),
            )
            results = []
            for name, helper, hash_helper in cases:
                with self.subTest(name=name):
                    with mock.patch.object(
                        release_bundle,
                        hash_helper,
                        side_effect=AssertionError("outside-root artifact must not be hashed"),
                    ) as digest_reader:
                        entry, blockers = helper(
                            outside,
                            bundle_root,
                            label="Release test artifact",
                            code="kagemusha_release_test_file_shape",
                        )
                    results.append((entry, blockers, digest_reader))

        for entry, blockers, digest_reader in results:
            self.assertIsNone(entry)
            digest_reader.assert_not_called()
            self.assertEqual(
                {item["code"] for item in blockers},
                {"kagemusha_release_bundle_path_outside_root"},
            )
            self.assertNotIn("outside bytes must not be hashed", json.dumps(blockers))

    def test_kagemusha_release_bundle_evidence_entry_rejects_symlink_swap_after_preflight(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as temp:
            bundle_root = Path(temp) / "bundle"
            bundle_root.mkdir()
            artifact = bundle_root / "artifact.bin"
            target = bundle_root / "target.bin"
            artifact.write_bytes(b"release artifact bytes")
            target.write_bytes(b"target artifact bytes")
            original_validate_local_file_for_read = (
                release_bundle._validate_local_file_for_read
            )
            swapped = False

            def swapping_validate_local_file_for_read(
                path: Path,
                label: str,
                code: str,
            ) -> tuple[os.stat_result | None, list[dict[str, object]]]:
                nonlocal swapped
                expected_stat, blockers = original_validate_local_file_for_read(
                    path,
                    label,
                    code,
                )
                if path == artifact and not blockers and not swapped:
                    slot_helpers.replace_with_symlink(self, artifact, target)
                    swapped = True
                return expected_stat, blockers

            with mock.patch.object(
                release_bundle,
                "_validate_local_file_for_read",
                swapping_validate_local_file_for_read,
            ):
                entry, blockers = release_bundle._evidence_entry_with_size(
                    artifact,
                    bundle_root,
                    label="Release test artifact",
                    code="kagemusha_release_test_file_shape",
                )

            target_bytes = target.read_bytes()

        self.assertIsNone(entry)
        self.assertEqual(target_bytes, b"target artifact bytes")
        self.assertIn(
            "kagemusha_release_test_file_shape",
            {item["code"] for item in blockers},
        )
        self.assertIn("must not be a symlink", blockers[0]["message"])

