                        "--repo-root",
                        str(REPO_ROOT),
                        "--device-lab-root",
                        str(linked_root),
                        "--lineage-proof-evidence",
                        str(lineage_evidence),
                        "--trusted-signer-public-key",
                        str(signer["public_key"]),
