        for command, expected_error, forbidden in cases:
            with self.subTest(expected_error=expected_error):
                with tempfile.TemporaryDirectory() as temp:
                    root = Path(temp)
                    staged_artifact_dir = root / "staged" / "artifacts" / "kagemusha"
